		// src/ccswitch/i18n/index.ts
		var DEFAULT_LANGUAGE = "zh";
		var getInitialLanguage = () => {
		  if (typeof window !== "undefined") {
		    try {
		      const stored = window.localStorage.getItem("language");
		      if (stored === "zh" || stored === "zh-TW" || stored === "en" || stored === "ja") {
		        return stored;
		      }
		    } catch (error) {
		      console.warn("[i18n] Failed to read stored language preference", error);
		    }
		  }
		  const navigatorLang = typeof navigator !== "undefined" ? navigator.language?.toLowerCase() ?? navigator.languages?.[0]?.toLowerCase() : void 0;
		  if (navigatorLang === "zh") {
		    return "zh";
		  }
		  if (navigatorLang?.startsWith("zh-tw") || navigatorLang?.startsWith("zh-hk") || navigatorLang?.startsWith("zh-mo") || navigatorLang?.startsWith("zh-hant")) {
		    return "zh-TW";
		  }
		  if (navigatorLang?.startsWith("zh")) {
		    return "zh";
		  }
		  if (navigatorLang?.startsWith("ja")) {
		    return "ja";
		  }
		  if (navigatorLang?.startsWith("en")) {
		    return "en";
		  }
		  return DEFAULT_LANGUAGE;
		};
		var resources = {
		  en: {
		    translation: en_default
		  },
		  ja: {
		    translation: ja_default
		  },
		  zh: {
		    translation: zh_default
		  },
		  "zh-TW": {
		    translation: zh_TW_default
		  }
		};
		instance.use(initReactI18next).init({
		  resources,
		  lng: getInitialLanguage(),
		  // 根据本地存储或系统语言选择默认语言
		  fallbackLng: "en",
		  // 如果缺少中文翻译则退回英文
		  interpolation: {
		    escapeValue: false
		    // React 已经默认转义
		  },
		  // 开发模式下显示调试信息
		  debug: false
		});

